__NUXT_JSONP__("/kr/how-to-apply", (function(a){return {data:[{details:{slug:"kr",pageTitle:"등록 방법 | Mentor Language Institute",pageDescription:a,title:"등록 방법",image:"\u002Fimages\u002Fhow-to-apply\u002Fhow-to-apply\u002Fmentors-mli.jpg",category:[{title:a,content:[{subtitle:"해외에서 등록하는 학생",description:["MLI를 통해서 학생 비자를 신청하고 다른 나라에서 신청하는 학생.\u003Cbr \u002F\u003E\u003Ca href='\u002Fkr\u002Fhow-to-apply\u002Foverseas' target='_blank'\u003E나머지 보기\u003C\u002Fa\u003E"]},{subtitle:"학교를 옮기는 학생",description:["미국에 현재 있고 Mentor Language Institute로 학교를 옮기는 학생. \u003Cbr \u002F\u003E\u003Ca href='\u002Fkr\u002Fhow-to-apply\u002Fstudent-visa-f1\u002Ftransfer-students' target='_blank'\u003E나머지 보기\u003C\u002Fa\u003E"]},{subtitle:"신분 변경",description:["미국에서의 신분을 학생 신분으로 변경을 원하는 학생\u003Cbr \u002F\u003E\u003Ca href='\u002Fkr\u002Fhow-to-apply\u002Fstudent-visa-f1\u002Fchange-of-status' target='_blank'\u003E나머지 보기\u003C\u002Fa\u003E"]},{subtitle:"비 F1 학생",description:["F1 비자가 아닌 다른 미국 비자를 가지고 있는 학생\u003Cbr \u002F\u003E\u003Ca href='\u002Fkr\u002Fhow-to-apply\u002Fnonf1' target='_blank'\u003E나머지 보기\u003C\u002Fa\u003E"]}]}],content:["영어 뿐만아니라, MLI는 8개 언어로 학생들을 지원합니다.\u003Cbr \u002F\u003E 문의 사항이 있으시면, 언제든지 질문 페이지를 통해서 저희에게 연락주세요."],dir:"\u002Fhow-to-apply",path:"\u002Fhow-to-apply\u002Fkr",extension:".json",createdAt:"2026-10-22T16:31:29.648Z",updatedAt:"2025-05-26T12:06:27.790Z"}}],fetch:{},mutations:void 0}}("Mentor Language Institute에 등록하기 위해 알아야하는 모든것")));